  "implementation": "def solve(case):
    refinement = case['refinement']
    edges = case['edges']
    members = {}
    for vertex, group in refinement.items():
        members.setdefault(group, []).append(vertex)
    agg = {}
    for v1, v2, w in edges:
        g1 = refinement[v1]
        g2 = refinement[v2]
        key = tuple(sorted((g1, g2)))
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = [list(key) + [w] for key, w in agg.items()]
    return {'aggregate_edges': aggregate_edges, 'members': members}
